INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(4550, 'off-balance-sheet', '/ˌɒf ˈbæləns ʃiːt/', 'adjective', '{"zh-TW":["表外的；資產負債表外的"],"en":["referring to assets or liabilities not recorded on the balance sheet"]}', NULL, 'off-balance-sheet financing / off-balance-sheet liability', '[{"en":"Operating leases can keep debt off-balance-sheet under older accounting rules.","zh-TW":"在較舊的會計準則下，經營租賃可以將債務保持在表外。"},{"en":"Off-balance-sheet items can obscure the true financial position of a company.","zh-TW":"表外項目可能掩蓋公司的真實財務狀況。"}]', NULL, NULL, 5, 4550, NULL),
(4551, 'off-peak', '/''ɒf piːk/', 'adjective', '{"zh-TW":["非高峰期的；淡季的"],"en":["occurring or used outside of the busiest time"]}', NULL, 'off-peak travel / off-peak discount / off-peak hours', '[{"en":"Traveling off-peak is a great way to save money and avoid crowded attractions.","zh-TW":"在非高峰期旅行是省錢和避開擁擠景點的好方法。"},{"en":"Many transport services offer off-peak fares to encourage travel at quieter times.","zh-TW":"許多交通服務提供非高峰期票價，以鼓勵在較清靜的時間出行。"}]', '{"noun2":"off-peak period"}', NULL, 3, 4551, NULL),
(4552, 'off-plan', '/ˌɒf ˈplæn/', 'adjective', '{"zh-TW":["按圖紙購買的；期房的"],"en":["bought or sold based on plans before a property is built"]}', NULL, 'buy off-plan / off-plan purchase / off-plan development', '[{"en":"She purchased the apartment off-plan at a discounted price.","zh-TW":"她以折扣價購買了期房公寓。"},{"en":"Off-plan purchases carry more risk but offer better initial pricing.","zh-TW":"期房購買風險更高，但提供更好的初始定價。"}]', NULL, NULL, 3, 4552, NULL),
(4553, 'off-season', '/''ɒf ˌsiːzən/', 'noun', '{"zh-TW":["淡季；非旺季"],"en":["a time of year when a place or service is less busy or popular"]}', NULL, 'travel off-season / off-season discount / off-season rates', '[{"en":"Off-season travel offers lower prices and fewer crowds at popular destinations.","zh-TW":"淡季旅行在熱門目的地提供更低的價格和更少的人群。"},{"en":"Visiting in the off-season allows you to explore attractions without the usual rush.","zh-TW":"在淡季參觀讓你可以在沒有通常的人流的情況下探索景點。"}]', NULL, NULL, 4, 4553, NULL),
(4554, 'offboarding', '/ˈɒfˌbɔːrdɪŋ/', 'noun', '{"zh-TW":["離職流程"],"en":["the process of managing an employee''s departure from a company"]}', NULL, 'offboarding checklist / offboarding process / employee offboarding', '[{"en":"The HR team conducted an offboarding interview with departing staff.","zh-TW":"人力資源團隊對離職員工進行了離職面談。"},{"en":"Proper offboarding ensures knowledge is transferred before departure.","zh-TW":"適當的離職流程確保在離職前完成知識轉移。"}]', '{"verb":"offboard"}', NULL, 4, 4554, NULL),
(4555, 'offer', '/ˈɒfər/', 'noun', '{"zh-TW":["提議；出價；優惠","提供；提議"],"en":["something proposed or available","a reduced price for a limited time","to present for acceptance"]}', '{"prefix":{"text":"of-","meaning":"toward (朝向)"},"root":{"text":"fer","meaning":"carry (帶來)"},"logic":"帶向某人，即「提供」。"}', 'special offer / make an offer; offer a discount / job offer / make an offer', '[{"en":"The store has a special offer on electronics.","zh-TW":"這家店有電子產品特惠。"},{"en":"He made an offer on the house.","zh-TW":"他對那棟房子出了價。"},{"en":"They offered me a position in marketing.","zh-TW":"他們給我一個行銷職位。"},{"en":"We offer a 15% discount on bulk orders.","zh-TW":"大量訂購可享15%折扣。"}]', '{"verb":"offer","noun":"offer, offering"}', NULL, 2, 4555, 165),
(4556, 'offer letter', '/ˈɒfər ˈletər/', 'noun', '{"zh-TW":["錄取通知書；offer函"],"en":["a formal written offer of employment to a job candidate"]}', NULL, 'receive an offer letter / send an offer letter / sign the offer letter', '[{"en":"She received an offer letter with a generous compensation package.","zh-TW":"她收到了一封附有豐厚薪酬方案的錄取通知書。"},{"en":"The offer letter outlined the start date, salary, and benefits.","zh-TW":"錄取通知書說明了入職日期、薪資和福利。"}]', NULL, NULL, 4, 4556, NULL),
(4557, 'offer price', '/ˈɒfər praɪs/', 'noun', '{"zh-TW":["要約價；報價"],"en":["the price at which something is offered for sale"]}', NULL, 'accept the offer price / negotiate the offer price', '[{"en":"The offer price for the shares was set at 10 dollars each.","zh-TW":"股份的要約價定為每股10元。"},{"en":"Investors accepted the offer price after reviewing the acquisition terms.","zh-TW":"投資者審閱收購條款後接受了要約價。"}]', NULL, NULL, 4, 4557, NULL),
(4558, 'office', '/ˈɒfɪs/', 'noun', '{"zh-TW":["辦公室"],"en":["a place where business work is done"]}', NULL, 'head office / office supplies', '[{"en":"Our head office is in Taipei.","zh-TW":"我們的總部在台北。"},{"en":"Order office supplies from the catalog.","zh-TW":"從目錄訂購辦公用品。"}]', '{"noun":"office","noun2":"officer","adjective":"official","adverb":"officially"}', NULL, 2, 4558, NULL),
(4559, 'office space', '/ˈɒfɪs speɪs/', 'noun', '{"zh-TW":["辦公空間"],"en":["an area used for carrying out business and administrative work"]}', NULL, 'rent office space / flexible office space / coworking office space', '[{"en":"The company leased new office space to accommodate growth.","zh-TW":"公司租用了新辦公空間以適應增長需求。"},{"en":"Flexible office space arrangements have become popular post-pandemic.","zh-TW":"靈活的辦公空間安排在疫情後變得流行。"}]', NULL, NULL, 4, 4559, NULL),
(4560, 'office supplies', '/ˈɒfɪs səˈplaɪz/', 'noun', '{"zh-TW":["辦公用品"],"en":["materials used in an office environment"]}', NULL, 'order office supplies / restock office supplies', '[{"en":"She ordered office supplies including paper, pens, and folders.","zh-TW":"她訂購了辦公用品，包括紙張、筆和資料夾。"},{"en":"Keep office supplies organized in clearly labeled storage.","zh-TW":"將辦公用品整齊地存放在有清晰標籤的地方。"}]', NULL, NULL, 5, 4560, NULL),
(4561, 'officer of the court', '/ˈɒfɪsər əv ðə kɔːrt/', 'noun', '{"zh-TW":["法庭人員"],"en":["a person such as a lawyer, receiver, or administrator acting under court authority"]}', NULL, 'act as an officer of the court / officer of the court responsibility', '[{"en":"The receiver was appointed as an officer of the court to manage the estate.","zh-TW":"接管人被任命為法庭人員以管理資產。"},{"en":"An officer of the court has legal and ethical obligations beyond their client.","zh-TW":"法庭人員對其客戶之外有法律和道德義務。"}]', NULL, NULL, 5, 4561, NULL),
(4562, 'official', 'əˈfɪʃəl', 'adjective', '{"zh-TW":["官方的；正式的","公認的"],"en":["authorized by authority","formal"]}', NULL, 'official document/official approval', '[{"en":"Please use the official company letterhead.","zh-TW":"請使用公司官方信紙。"}]', '{"noun":"official","adverb":"officially"}', NULL, 3, 4562, 166),
(4563, 'official statement', '/''əˌfɪʃəl ˌsteɪtmənt/', 'noun', '{"zh-TW":["官方聲明；正式聲明"],"en":["a formal announcement made by an organization or official on a particular issue"]}', NULL, 'release an official statement / official statement from / issue an official statement', '[{"en":"The company released an official statement denying the allegations.","zh-TW":"公司發布了一份否認指控的官方聲明。"},{"en":"The government issued an official statement clarifying the new policy measures.","zh-TW":"政府發布了一份官方聲明，澄清了新的政策措施。"}]', NULL, NULL, 5, 4563, NULL),
(4564, 'offset', '/ˈɒfsɛt/', 'verb', '{"zh-TW":["抵消；彌補"],"en":["to balance or compensate"]}', '{"prefix":{"text":"off-","meaning":"away"},"root":{"text":"set","meaning":"place (放)"}}', 'offset costs / offset losses', '[{"en":"The gains offset the earlier losses.","zh-TW":"收益抵消了早期損失。"},{"en":"Higher sales offset increased costs.","zh-TW":"更高銷售額抵消了成本增加。"}]', '{"noun":"offset"}', NULL, 2, 4564, 701),
(4565, 'offshore', '/ˈɒfʃɔːr/', 'adjective', '{"zh-TW":["境外的；離岸的"],"en":["located or occurring outside one''s home country"]}', NULL, 'offshore account / offshore investment / offshore manufacturing', '[{"en":"The company opened an offshore account to manage foreign currency.","zh-TW":"公司開設了一個境外帳戶來管理外幣。"},{"en":"Offshore manufacturing reduced production costs significantly.","zh-TW":"境外製造顯著降低了生產成本。"}]', '{"verb":"offshore","adverb":"offshore"}', NULL, 3, 4565, NULL),
(4566, 'offshore account', '/ˈɒfʃɔːr əˈkaʊnt/', 'noun', '{"zh-TW":["離岸帳戶"],"en":["a bank account held in a foreign country, often for tax or legal reasons"]}', NULL, 'open an offshore account / offshore account regulations', '[{"en":"The company held an offshore account to manage foreign currency receipts.","zh-TW":"公司持有離岸帳戶以管理外幣收款。"},{"en":"Offshore accounts must comply with international tax reporting requirements.","zh-TW":"離岸帳戶必須遵守國際稅務申報要求。"}]', NULL, NULL, 5, 4566, NULL),
(4567, 'offshore banking', '/ˈɒfʃɔːr ˈbæŋkɪŋ/', 'noun', '{"zh-TW":["離岸銀行業務"],"en":["banking services offered in a foreign jurisdiction, often for tax advantages"]}', NULL, 'use offshore banking / offshore banking account', '[{"en":"Multinational companies use offshore banking for treasury operations.","zh-TW":"跨國公司使用離岸銀行業務進行財資運作。"},{"en":"Offshore banking must comply with anti-money laundering regulations.","zh-TW":"離岸銀行業務必須遵守反洗錢法規。"}]', NULL, NULL, 5, 4567, NULL),
(4568, 'offshoring', '/ˈɒfʃɔːrɪŋ/', 'noun', '{"zh-TW":["離岸外包；境外遷移"],"en":["moving business operations to a foreign country"]}', NULL, 'offshoring of jobs / offshoring strategy', '[{"en":"Offshoring manufacturing helped reduce production costs.","zh-TW":"將製造業務遷移海外有助於降低生產成本。"},{"en":"Critics argue that offshoring harms domestic workers.","zh-TW":"批評者認為離岸外包損害了本國工人的利益。"}]', '{"verb":"offshore","adjective":"offshore"}', NULL, 4, 4568, NULL),
(4569, 'offsite', '/ˈɒfsaɪt/', 'adjective', '{"zh-TW":["場外的；外地的"],"en":["taking place or located away from the main workplace or premises"]}', NULL, 'offsite meeting / offsite training / offsite team building', '[{"en":"The management team held an offsite retreat for strategic planning.","zh-TW":"管理團隊舉行了外地靜修活動進行策略規劃。"},{"en":"Offsite data storage provides protection against local disasters.","zh-TW":"場外資料存儲提供了對本地災難的保護。"}]', '{"adverb":"offsite"}', NULL, 3, 4569, NULL),
(4570, 'oil price', '/ɔɪl praɪs/', 'noun', '{"zh-TW":["油價"],"en":["the market price for crude oil per barrel"]}', NULL, 'rising oil prices / oil price volatility', '[{"en":"Rising oil prices increased transportation costs for businesses.","zh-TW":"上漲的油價增加了企業的運輸成本。"},{"en":"The company hedged against oil price increases using futures contracts.","zh-TW":"公司使用期貨合約對沖油價上漲風險。"}]', NULL, NULL, 3, 4570, NULL),
(4571, 'OKR', '/ˌoʊ keɪ ˈɑːr/', 'noun', '{"zh-TW":["目標與關鍵結果"],"en":["objectives and key results; a goal-setting framework"]}', NULL, 'set OKRs / OKR framework / quarterly OKRs', '[{"en":"The company adopted OKRs to align team and company goals.","zh-TW":"公司採用OKR框架使團隊和公司目標保持一致。"},{"en":"Each department reviews OKR progress at the end of each quarter.","zh-TW":"每個部門在每季末審查OKR進度。"}]', '{"full form":"objectives and key results"}', NULL, 1, 4571, NULL),
(4572, 'old', '/oʊld/', 'adjective', '{"zh-TW":["舊的；老的"],"en":["having existed for a long time","of a particular age"]}', NULL, 'years old / old-fashioned', '[{"en":"The building is 50 years old.","zh-TW":"這棟大樓有50年歷史。"},{"en":"That approach is old-fashioned now.","zh-TW":"那個方法現在已經過時了。"}]', '{"adjective":"old","noun":"age","verb":"age"}', NULL, 1, 4572, NULL),
(4573, 'oligarchy', '/ˈɒlɪɡɑːrki/', 'noun', '{"zh-TW":["寡頭政治；寡頭政府"],"en":["a small group of people having control of a country or organization"]}', NULL, 'political oligarchy / economic oligarchy / ruling oligarchy', '[{"en":"Critics argued that post-Soviet Russia evolved into a corrupt oligarchy.","zh-TW":"批評者認為，蘇聯解體後的俄羅斯演變成了腐敗的寡頭政治。"},{"en":"Corporate oligarchies may form when a few dominant companies control an entire industry.","zh-TW":"當少數主導公司控制整個行業時，可能形成企業寡頭政治。"}]', '{"adjective":"oligarchic","noun2":"oligarch"}', NULL, 3, 4573, NULL),
(4574, 'oligopoly', '/ˌɒlɪˈɡɒpəli/', 'noun', '{"zh-TW":["寡占市場；少數壟斷"],"en":["a state in which a market is dominated by a few large sellers"]}', NULL, 'form an oligopoly / oligopoly pricing / oligopolistic market', '[{"en":"The airline industry operates as an oligopoly in most national markets.","zh-TW":"航空業在大多數國家市場中以寡占方式運作。"},{"en":"An oligopoly may lead to price coordination among dominant firms.","zh-TW":"寡占市場可能導致主導企業之間的價格協調。"}]', '{"adjective":"oligopolistic"}', NULL, 3, 4574, NULL),
(4575, 'ombudsman', '/ˈɒmbʊdzmən/', 'noun', '{"zh-TW":["監察專員；投訴調解專員"],"en":["an official appointed to investigate complaints made by citizens or customers"]}', NULL, 'financial ombudsman / banking ombudsman / contact the ombudsman', '[{"en":"The financial ombudsman resolved the disputed insurance claim.","zh-TW":"金融監察專員解決了有爭議的保險索賠。"},{"en":"She filed a complaint with the banking ombudsman after the bank rejected her claim.","zh-TW":"在銀行拒絕她的索賠後，她向銀行監察專員提出了投訴。"}]', '{"plural":"ombudsmen"}', NULL, 3, 4575, NULL),
(4576, 'omission', '/əˈmɪʃən/', 'noun', '{"zh-TW":["遺漏；省略；不作為"],"en":["something that has been left out or excluded; a failure to act"]}', NULL, 'material omission / negligent omission / omission of information', '[{"en":"The omission of key financial data from the report misled investors.","zh-TW":"報告中遺漏了關鍵財務數據，誤導了投資者。"},{"en":"Negligent omission in a contract may be as damaging as a deliberate misrepresentation.","zh-TW":"合同中的疏忽性遺漏可能與故意虛假陳述一樣有害。"}]', '{"verb":"omit","adjective":"omitted"}', NULL, 3, 4576, NULL),
(4577, 'omnichannel', '/ˈɒmniˌtʃænəl/', 'adjective', '{"zh-TW":["全渠道的；多渠道整合的"],"en":["providing a seamless customer experience across all channels"]}', NULL, 'omnichannel strategy / omnichannel retail / omnichannel approach', '[{"en":"The retailer''s omnichannel strategy unified online and offline experiences.","zh-TW":"零售商的全渠道策略統一了線上和線下體驗。"},{"en":"Omnichannel customers spend more than single-channel shoppers.","zh-TW":"全渠道客戶比單一渠道購物者花費更多。"}]', '{"noun":"omnichannel"}', NULL, 4, 4577, NULL),
(4578, 'omnipresent', '/''ɒmnɪˌprezənt/', 'adjective', '{"zh-TW":["無所不在的；普遍存在的"],"en":["present in all places at all times; widely or constantly encountered"]}', NULL, 'omnipresent technology / omnipresent influence / omnipresent media', '[{"en":"Smartphones have become omnipresent in modern society, influencing every aspect of life.","zh-TW":"智能手機在現代社會無處不在，影響著生活的每個方面。"},{"en":"Social media is omnipresent, shaping public opinion and behavior around the world.","zh-TW":"社交媒體無所不在，影響著世界各地的公眾輿論和行為。"}]', '{"noun":"omnipresence","adverb":"omnipresently"}', NULL, 4, 4578, NULL),
(4579, 'on-boarding', '/ˈɒn bɔːrdɪŋ/', 'noun', '{"zh-TW":["入職培訓；系統導入"],"en":["the process of integrating new employees or customers into an organization or system"]}', NULL, 'design an on-boarding process / on-boarding program', '[{"en":"A structured on-boarding program reduced new hire time-to-productivity.","zh-TW":"結構化的入職培訓計劃縮短了新員工達到生產效率所需的時間。"},{"en":"Customer on-boarding includes account setup and initial product training.","zh-TW":"客戶系統導入包括帳戶設置和初始產品培訓。"}]', NULL, NULL, 4, 4579, NULL),
(4580, 'on-site', '/ˌɒn ˈsaɪt/', 'adjective', '{"zh-TW":["現場的；現地的"],"en":["taking place or located at the location where work is happening"]}', NULL, 'on-site training / on-site team / on-site inspection', '[{"en":"An on-site inspection was conducted before approving the facility.","zh-TW":"在批准設施前進行了現場檢查。"},{"en":"On-site support reduced resolution times for technical problems.","zh-TW":"現場支援縮短了技術問題的解決時間。"}]', NULL, NULL, 3, 4580, NULL),
(4581, 'on-site restaurant', '/ɒn saɪt ˈrɛstrɒnt/', 'noun', '{"zh-TW":["飯店內附設餐廳"],"en":["a restaurant located within a hotel or facility"]}', NULL, 'dine at the on-site restaurant / on-site restaurant menu', '[{"en":"The on-site restaurant serves international cuisine.","zh-TW":"飯店內附設餐廳供應國際料理。"},{"en":"Guests receive a 15% discount at the on-site restaurant.","zh-TW":"住客在飯店內附設餐廳享有八五折優惠。"}]', NULL, NULL, 5, 4581, NULL),
(4582, 'on-the-job training', '/ɒn ðə dʒɒb ˈtreɪnɪŋ/', 'noun', '{"zh-TW":["在職培訓"],"en":["training received while performing the job"]}', NULL, 'receive on-the-job training / provide on-the-job training', '[{"en":"New employees receive on-the-job training for the first two weeks.","zh-TW":"新員工在前兩週接受在職培訓。"},{"en":"On-the-job training is often more effective than classroom instruction.","zh-TW":"在職培訓通常比課堂教學更有效。"}]', NULL, NULL, 5, 4582, NULL),
(4583, 'on-time', 'ɒn taɪm', 'adjective', '{"zh-TW":["準時的；按時的","及時的"],"en":["arriving at the correct time","not late"]}', NULL, 'on-time delivery/on-time payment', '[{"en":"On-time delivery is critical to our service.","zh-TW":"準時交付對我們的服務至關重要。"}]', '{"adverb":"on time"}', NULL, 3, 4583, NULL),
(4584, 'onboard', '/ˈɒnbɔːrd/', 'verb', '{"zh-TW":["入職；使適應"],"en":["to integrate a new employee or client into an organization"]}', NULL, 'onboard new hires / client onboarding process', '[{"en":"New employees are onboarded through a two-week orientation program.","zh-TW":"新員工通過兩週的入職培訓計劃完成入職。"},{"en":"The company streamlined its client onboarding process to reduce friction.","zh-TW":"公司精簡了客戶入職流程以減少阻力。"}]', '{"noun":"onboarding","adjective":"onboarded"}', NULL, 3, 4584, NULL),
(4585, 'onboarding', '/ˈɒnˌbɔːrdɪŋ/', 'noun', '{"zh-TW":["入職培訓；新員工導入"],"en":["the process of integrating a new employee into an organization"]}', NULL, 'onboarding program / smooth onboarding / onboarding process', '[{"en":"A structured onboarding program helps new hires settle in quickly.","zh-TW":"有組織的入職培訓計劃幫助新員工快速融入。"},{"en":"Remote onboarding requires extra effort to build team connections.","zh-TW":"遠端入職培訓需要額外努力建立團隊聯繫。"}]', '{"verb":"onboard"}', NULL, 4, 4585, NULL),
(4586, 'onboarding experience', '/ˈɒnˌbɔːrdɪŋ ɪkˈspɪəriənts/', 'noun', '{"zh-TW":["入職體驗；客戶開通體驗"],"en":["the initial experience of a new customer or employee joining a service or company"]}', NULL, 'improve onboarding experience / seamless onboarding experience', '[{"en":"A smooth onboarding experience reduces early customer churn.","zh-TW":"順暢的開通體驗減少了早期客戶流失。"},{"en":"The app''s onboarding experience guided users through key features.","zh-TW":"應用程式的入門體驗引導用戶了解關鍵功能。"}]', NULL, NULL, 5, 4586, NULL),
(4587, 'onboarding process', '/ˈɒnbɔːrdɪŋ ˈprɒses/', 'noun', '{"zh-TW":["入職流程"],"en":["the process of integrating a new employee or client into an organization"]}', NULL, 'improve the onboarding process / onboarding process checklist', '[{"en":"A structured onboarding process helps new hires become productive faster.","zh-TW":"結構化的入職流程幫助新員工更快地提高生產力。"},{"en":"The client onboarding process involves identity verification and account setup.","zh-TW":"客戶入職流程包括身份驗證和帳戶設置。"}]', NULL, NULL, 5, 4587, NULL),
(4588, 'oncology', '/ɒnˈkɒlədʒi/', 'noun', '{"zh-TW":["腫瘤學；腫瘤科"],"en":["the branch of medicine dealing with cancer"]}', NULL, 'oncology treatment / oncology specialist', '[{"en":"She is receiving oncology treatment for breast cancer.","zh-TW":"她正在接受乳癌的腫瘤治療。"},{"en":"Advances in oncology have improved cancer survival rates.","zh-TW":"腫瘤學的進步提高了癌症存活率。"}]', '{"noun":"oncologist","adjective":"oncological"}', NULL, 3, 4588, NULL),
(4589, 'one-way ticket', '/wʌn weɪ ˈtɪkɪt/', 'noun', '{"zh-TW":["單程票"],"en":["a ticket valid for travel in one direction only"]}', NULL, 'buy a one-way ticket / one-way ticket price', '[{"en":"She bought a one-way ticket to start a new life abroad.","zh-TW":"她買了一張單程票，開始在國外的新生活。"},{"en":"A one-way ticket is often more expensive than half a roundtrip.","zh-TW":"單程票通常比來回票的一半還貴。"}]', NULL, NULL, 5, 4589, NULL),
(4590, 'onerous', '/ˈɒnərəs/', 'adjective', '{"zh-TW":["繁重的；費力的"],"en":["involving heavy obligations or burdensome duties"]}', NULL, 'onerous regulation / onerous task / onerous condition', '[{"en":"The onerous reporting requirements imposed significant compliance costs on small firms.","zh-TW":"繁重的報告要求給小企業帶來了巨大的合規成本。"},{"en":"Both sides agreed to remove the most onerous clauses from the contract.","zh-TW":"雙方同意從合同中刪除最繁重的條款。"}]', '{"adverb":"onerously","noun":"onerousness"}', NULL, 3, 4590, NULL),
(4591, 'ongoing', '/ˈɒnɡoʊɪŋ/', 'adjective', '{"zh-TW":["持續進行的"],"en":["continuing; still in progress"]}', NULL, 'ongoing process / ongoing project', '[{"en":"The investigation is still ongoing.","zh-TW":"調查仍在進行中。"},{"en":"We provide ongoing training for staff.","zh-TW":"我們提供持續培訓。"}]', NULL, NULL, 3, 4591, 401),
(4592, 'online banking', '/ˈɒnlaɪn ˈbæŋkɪŋ/', 'noun', '{"zh-TW":["網路銀行；線上銀行"],"en":["banking services accessed via the internet"]}', NULL, 'use online banking / online banking security', '[{"en":"Online banking makes it easy to manage your finances anywhere.","zh-TW":"網路銀行使您可以在任何地方輕鬆管理財務。"},{"en":"Always log out after using online banking on a public computer.","zh-TW":"在公共電腦上使用網路銀行後請務必登出。"}]', NULL, NULL, 5, 4592, NULL),
(4593, 'online course', '/ˈɒnlaɪn kɔːrs/', 'noun', '{"zh-TW":["線上課程"],"en":["a course delivered through the internet"]}', NULL, 'enroll in an online course / complete an online course', '[{"en":"She took an online course to improve her data skills.","zh-TW":"她參加了一門線上課程以提升數據技能。"},{"en":"Online courses offer flexibility for working adults.","zh-TW":"線上課程為在職成人提供了靈活性。"}]', NULL, NULL, 5, 4593, NULL),
(4594, 'online marketplace', '/ˈɒnlaɪn ˈmɑːrkɪtpleɪs/', 'noun', '{"zh-TW":["線上交易平台；電商平台"],"en":["a digital platform where buyers and sellers transact"]}', NULL, 'sell on an online marketplace / online marketplace fees', '[{"en":"The company listed its products on three major online marketplaces.","zh-TW":"公司在三個主要線上交易平台上列出了其產品。"},{"en":"Online marketplace fees eat into seller margins.","zh-TW":"線上交易平台費用侵蝕了賣家的利潤率。"}]', NULL, NULL, 5, 4594, NULL),
(4595, 'onshore', '/ˈɒnʃɔːr/', 'adjective', '{"zh-TW":["在岸的；國內的"],"en":["located or occurring within a particular country"]}', NULL, 'onshore banking / onshore operations / onshore investment', '[{"en":"The company moved its treasury operations onshore for compliance.","zh-TW":"公司將其財資業務移至境內以符合合規要求。"},{"en":"Onshore manufacturing reduced logistics complexity.","zh-TW":"在岸製造降低了物流複雜性。"}]', '{"opposite":"offshore"}', NULL, 3, 4595, NULL),
(4596, 'onsite', '/ˈɒnsaɪt/', 'adjective', '{"zh-TW":["現場的；在地的"],"en":["taking place or located at the main workplace or facility"]}', NULL, 'onsite inspection / onsite support / onsite training', '[{"en":"An onsite inspection confirmed the safety standards were met.","zh-TW":"現場檢查確認達到了安全標準。"},{"en":"Onsite support is available Monday through Friday.","zh-TW":"週一至週五提供現場技術支援。"}]', '{"adverb":"onsite"}', NULL, 2, 4596, NULL),
(4597, 'ontology', '/ɒnˈtɒlədʒi/', 'noun', '{"zh-TW":["本體論；存在論"],"en":["the branch of philosophy concerned with the nature of existence"]}', NULL, 'research ontology / philosophical ontology / ontology of a system', '[{"en":"The researcher clarified the ontology underlying the study.","zh-TW":"研究員闡明了研究所依據的本體論。"},{"en":"Different ontologies lead to different research methodologies.","zh-TW":"不同的本體論導致不同的研究方法論。"}]', '{"adjective":"ontological","adverb":"ontologically"}', NULL, 3, 4597, NULL),
(4598, 'opaque', '/''əʊˌpeɪk/', 'adjective', '{"zh-TW":["不透明的；難以理解的"],"en":["not able to be seen through; not transparent; not clearly understood"]}', NULL, 'opaque process / opaque language / opaque system', '[{"en":"The company''s decision-making process was opaque, leading to distrust among employees.","zh-TW":"公司的決策流程不透明，導致員工之間產生不信任。"},{"en":"The legal document was full of opaque terminology that confused most readers.","zh-TW":"法律文件充滿了難以理解的術語，使大多數讀者感到困惑。"}]', '{"adverb":"opaquely","noun":"opacity"}', NULL, 2, 4598, NULL),
(4599, 'open', '/ˈoʊpən/', 'adjective', '{"zh-TW":["開放的；公開的"],"en":["not closed","available to everyone"]}', NULL, 'open position / open-minded', '[{"en":"We have an open position in marketing.","zh-TW":"我們行銷部有一個空缺職位。"},{"en":"Be open-minded about new ideas.","zh-TW":"對新想法保持開放的心態。"}]', '{"adjective":"open","verb":"open","noun":"opening","adverb":"openly"}', NULL, 1, 4599, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(4600, 'open account', '/ˈoʊpən əˈkaʊnt/', 'noun', '{"zh-TW":["賒帳；開放帳戶"],"en":["a trade credit arrangement where payment is made after goods are received"]}', NULL, 'sell on open account / open account terms', '[{"en":"Open account terms allow buyers to pay within 30 days of delivery.","zh-TW":"賒帳條款允許買方在交貨後30天內付款。"},{"en":"Open account trading is common among established business partners.","zh-TW":"賒帳交易在老業務夥伴之間很常見。"}]', NULL, NULL, 4, 4600, NULL),
(4601, 'open economy', '/ˈəʊpən ɪˈkɒnəmi/', 'noun', '{"zh-TW":["開放型經濟"],"en":["an economy that has significant foreign trade and investment flows"]}', NULL, 'large open economy / small open economy / transition to open economy', '[{"en":"A small open economy is highly sensitive to external shocks in global trade.","zh-TW":"小型開放型經濟體對全球貿易的外部衝擊高度敏感。"},{"en":"Liberalization policies transformed the country from a closed to an open economy.","zh-TW":"自由化政策使該國從封閉型經濟體轉變為開放型經濟體。"}]', NULL, NULL, 4, 4601, NULL),
(4602, 'open enrollment', '/''əʊpən ɪnˌrəʊlmənt/', 'noun', '{"zh-TW":["開放入學；不限制條件的招生"],"en":["a policy that allows any student to attend a school regardless of academic background or residency"]}', NULL, 'support open enrollment / open enrollment period / open enrollment program', '[{"en":"Open enrollment policies allow students to choose schools based on quality and fit.","zh-TW":"開放入學政策允許學生根據質量和適合度選擇學校。"},{"en":"During the open enrollment period, families can apply to any public school in the district.","zh-TW":"在開放入學期間，家庭可以申請該學區的任何公立學校。"}]', '{"verb":"enroll","noun":"enrollment"}', NULL, 5, 4602, NULL),
(4603, 'open house', '/''əʊpən haʊs/', 'noun', '{"zh-TW":["開放參觀；看房活動"],"en":["an event where a property for sale or rent is open for viewing by potential buyers or tenants"]}', NULL, 'host an open house / attend an open house / schedule an open house', '[{"en":"The agent held an open house on Sunday to attract potential buyers.","zh-TW":"經紀人週日舉辦了開放參觀活動，以吸引潛在買家。"},{"en":"An open house allows buyers to tour the property without a formal appointment.","zh-TW":"開放參觀讓買家無需正式預約即可參觀房產。"}]', NULL, NULL, 4, 4603, NULL),
(4604, 'open kitchen', '/ˈəʊpən ˈkɪtʃɪn/', 'noun', '{"zh-TW":["開放式廚房"],"en":["a kitchen visible to dining guests"]}', NULL, 'open kitchen design / dine with an open kitchen view', '[{"en":"The restaurant features an open kitchen where guests can watch the chefs.","zh-TW":"餐廳設有開放式廚房，賓客可以觀看廚師烹飪。"},{"en":"An open kitchen adds transparency and excitement to dining.","zh-TW":"開放式廚房為用餐增添了透明度和刺激感。"}]', NULL, NULL, 4, 4604, NULL),
(4605, 'open market', '/ˈoʊpən ˈmɑːrkɪt/', 'noun', '{"zh-TW":["公開市場"],"en":["a market with free competition where prices are determined by supply and demand"]}', NULL, 'trade in the open market / open market operations', '[{"en":"The company bought back shares on the open market.","zh-TW":"公司在公開市場上回購了股份。"},{"en":"Open market prices reflect real-time supply and demand.","zh-TW":"公開市場價格反映實時供需狀況。"}]', NULL, NULL, 4, 4605, NULL),
(4606, 'open purchase order', '/ˌoʊpən ˈpɜːrtʃɪs ˈɔːrdər/', 'noun', '{"zh-TW":["未結採購訂單；開放採購訂單"],"en":["a purchase order that has not yet been fully delivered or closed"]}', NULL, 'manage open purchase orders / open purchase order value', '[{"en":"The procurement team reviewed all open purchase orders each week.","zh-TW":"採購團隊每週審查所有未結採購訂單。"},{"en":"An open purchase order allows multiple deliveries against a single order.","zh-TW":"未結採購訂單允許針對單一訂單進行多次交貨。"}]', NULL, NULL, 5, 4606, NULL),
(4607, 'open source', '/ˈəʊpən sɔːrs/', 'adjective', '{"zh-TW":["開源的"],"en":["software with source code available for anyone to inspect, modify, and distribute"]}', NULL, 'open source software / open source community / open source license', '[{"en":"Linux is the most widely used open source operating system.","zh-TW":"Linux是使用最廣泛的開源作業系統。"},{"en":"The team decided to open source their internal tool to gain community contributions.","zh-TW":"團隊決定將其內部工具開源以獲得社區貢獻。"}]', '{"noun":"open source","verb":"open-source"}', NULL, 4, 4607, NULL),
(4608, 'open tender', '/ˈoʊpən ˈtendər/', 'noun', '{"zh-TW":["公開招標"],"en":["a procurement process where bids are invited publicly from any qualified supplier"]}', NULL, 'issue an open tender / open tender process', '[{"en":"The government issued an open tender for the construction of the new highway.","zh-TW":"政府為新公路建設發出了公開招標。"},{"en":"Open tender processes ensure transparency and competitive pricing.","zh-TW":"公開招標流程確保了透明度和競爭性定價。"}]', '{"synonym":"public tender","synonym2":"competitive bid"}', NULL, 4, 4608, NULL),
(4609, 'open-book accounting', '/ˈoʊpən bʊk əˈkaʊntɪŋ/', 'noun', '{"zh-TW":["開放帳目；公開帳目"],"en":["sharing financial records with a trading partner for transparency"]}', NULL, 'use open-book accounting / open-book accounting contract', '[{"en":"The construction contract operated on open-book accounting principles.","zh-TW":"建設合約在公開帳目原則下運作。"},{"en":"Open-book accounting builds trust between partners and clients.","zh-TW":"公開帳目在合作夥伴和客戶之間建立信任。"}]', NULL, NULL, 5, 4609, NULL),
(4610, 'open-ended fund', '/ˌoʊpən ˈendɪd fʌnd/', 'noun', '{"zh-TW":["開放式基金"],"en":["an investment fund with no fixed number of shares, allowing continuous entry and exit"]}', NULL, 'invest in an open-ended fund / open-ended fund redemption', '[{"en":"An open-ended fund allows investors to redeem shares at any time.","zh-TW":"開放式基金允許投資者隨時贖回股份。"},{"en":"Open-ended funds are priced daily based on net asset value.","zh-TW":"開放式基金根據淨資產值每日定價。"}]', '{"opposite":"closed-ended fund"}', NULL, 5, 4610, NULL),
(4611, 'open-ended question', '/ˈəʊpən ˌɛndɪd ˈkwɛstʃən/', 'noun', '{"zh-TW":["開放性問題"],"en":["a question requiring a detailed answer, not just yes or no"]}', NULL, 'ask an open-ended question / use open-ended questions', '[{"en":"Open-ended questions encourage more thoughtful responses.","zh-TW":"開放性問題鼓勵更有深度的回覆。"},{"en":"Interviewers use open-ended questions to assess candidates fully.","zh-TW":"面試官使用開放性問題全面評估候選人。"}]', NULL, NULL, 5, 4611, NULL),
(4612, 'operate', '/ˈɒpəreɪt/', 'verb', '{"zh-TW":["操作；運作","經營"],"en":["to work or function","to manage"]}', '{"root":{"text":"oper","meaning":"work (工作)"},"suffix":{"text":"-ate","meaning":"使..."}}', 'operate a business / operate machinery', '[{"en":"The company operates in over 30 countries.","zh-TW":"公司在30多國經營。"},{"en":"Only trained staff should operate this.","zh-TW":"只有培訓過的人員能操作。"}]', '{"noun":"operation, operator","adjective":"operational, operative"}', NULL, 3, 4612, 42),
(4613, 'operating budget', '/ˈɒpəreɪtɪŋ ˈbʌdʒɪt/', 'noun', '{"zh-TW":["營業預算；運營預算"],"en":["a financial plan for day-to-day business expenses"]}', NULL, 'approve the operating budget / exceed the operating budget', '[{"en":"The operating budget for next year was set at 5 million.","zh-TW":"下一年的運營預算設定為500萬元。"},{"en":"All departments submitted their plans for the annual operating budget.","zh-TW":"所有部門提交了年度運營預算計劃。"}]', NULL, NULL, 5, 4613, NULL),
(4614, 'operating cash flow', '/ˈɒpəreɪtɪŋ kæʃ floʊ/', 'noun', '{"zh-TW":["營業現金流"],"en":["cash generated from a company''s primary business activities"]}', NULL, 'measure operating cash flow / positive operating cash flow', '[{"en":"Operating cash flow exceeded net income due to strong collections.","zh-TW":"由於強勁的收款，營業現金流超過了淨利潤。"},{"en":"Analysts use operating cash flow to assess business quality.","zh-TW":"分析師使用營業現金流評估業務質量。"}]', NULL, NULL, 5, 4614, NULL),
(4615, 'operating company', '/ˈɒpəreɪtɪŋ ˈkʌmpəni/', 'noun', '{"zh-TW":["運營公司"],"en":["the entity within a corporate group that conducts actual business operations"]}', NULL, 'set up an operating company / operating company performance', '[{"en":"Each operating company reports results to the holding company.","zh-TW":"每家運營公司向控股公司報告業績。"},{"en":"The operating company was responsible for all customer-facing activities.","zh-TW":"運營公司負責所有面向客戶的活動。"}]', NULL, NULL, 5, 4615, NULL),
(4616, 'operating expenditure', '/ˈɒpəreɪtɪŋ ɪkˈspendɪtʃər/', 'noun', '{"zh-TW":["運營支出"],"en":["the ongoing costs of running a business day to day"]}', NULL, 'reduce operating expenditure / increase operating expenditure', '[{"en":"The company cut operating expenditure by 15% through efficiency measures.","zh-TW":"公司通過效率措施削減了15%的運營支出。"},{"en":"Operating expenditure is deducted from revenue to calculate operating profit.","zh-TW":"運營支出從收入中扣除以計算營業利潤。"}]', '{"abbreviation":"OPEX"}', NULL, 5, 4616, NULL),
(4617, 'operating expense', '/ˈɒpəreɪtɪŋ ɪkˈspens/', 'noun', '{"zh-TW":["運營費用；經營成本"],"en":["the ongoing costs incurred in running a business, excluding capital expenditures"]}', NULL, 'reduce operating expenses / operating expense ratio', '[{"en":"Rising operating expenses squeezed the company''s profit margins.","zh-TW":"不斷上升的運營費用壓縮了公司的利潤率。"},{"en":"Management set a target to reduce operating expenses by 10%.","zh-TW":"管理層設定了將運營費用降低10%的目標。"}]', '{"abbreviation":"OPEX","opposite":"capital expenditure"}', NULL, 5, 4617, NULL),
(4618, 'operating expenses', '/ˈɒpəreɪtɪŋ ɪkˈspensɪz/', 'noun', '{"zh-TW":["營運費用"],"en":["costs incurred through normal business operations"]}', NULL, 'control operating expenses / operating expenses ratio', '[{"en":"Operating expenses were kept below 30% of revenue.","zh-TW":"營運費用保持在收入的30%以下。"},{"en":"Reducing operating expenses directly improves operating profit.","zh-TW":"降低營運費用直接改善了營業利潤。"}]', '{"abbreviation":"OPEX","singular":"operating expense"}', NULL, 5, 4618, NULL),
(4619, 'operating income', '/ˈɒpəreɪtɪŋ ˈɪnkʌm/', 'noun', '{"zh-TW":["營業收入；營業利潤"],"en":["revenue minus operating expenses before interest and tax"]}', NULL, 'report operating income / improve operating income', '[{"en":"Operating income grew by 12% following the cost reduction initiative.","zh-TW":"在降成本計劃後，營業收入增長了12%。"},{"en":"A high operating income indicates strong core business performance.","zh-TW":"高營業收入表明核心業務表現強勁。"}]', '{"synonym":"EBIT","abbreviation":"EBIT"}', NULL, 5, 4619, NULL),
(4620, 'operating lease', '/ˈɒpəreɪtɪŋ liːs/', 'noun', '{"zh-TW":["營業租賃"],"en":["a lease where the lessor retains ownership and risk of the asset"]}', NULL, 'enter an operating lease / operating lease obligation', '[{"en":"Office space is often leased under an operating lease arrangement.","zh-TW":"辦公空間通常通過營業租賃安排租用。"},{"en":"Under new accounting standards, operating leases appear on the balance sheet.","zh-TW":"根據新會計標準，營業租賃出現在資產負債表上。"}]', NULL, NULL, 5, 4620, NULL),
(4621, 'operating leverage', '/ˈɒpəreɪtɪŋ ˈlevərɪdʒ/', 'noun', '{"zh-TW":["營運槓桿"],"en":["the ratio of fixed to variable costs, affecting profit sensitivity to revenue changes"]}', NULL, 'high operating leverage / manage operating leverage', '[{"en":"High operating leverage means small revenue increases can boost profits significantly.","zh-TW":"高營運槓桿意味著小幅的收入增加可以顯著提高利潤。"},{"en":"The company reduced operating leverage by converting fixed to variable costs.","zh-TW":"公司通過將固定成本轉換為可變成本降低了營運槓桿。"}]', NULL, NULL, 5, 4621, NULL),
(4622, 'operating margin', '/ˈɒpəreɪtɪŋ ˈmɑːrdʒɪn/', 'noun', '{"zh-TW":["營業利潤率"],"en":["the percentage of revenue remaining after deducting operating expenses"]}', NULL, 'improve operating margin / operating margin target', '[{"en":"The company''s operating margin improved from 12% to 15% after restructuring.","zh-TW":"重組後，公司的營業利潤率從12%提高到了15%。"},{"en":"Analysts compare operating margin across peers to assess efficiency.","zh-TW":"分析師比較同行業的營業利潤率以評估效率。"}]', NULL, NULL, 5, 4622, NULL),
(4623, 'operating model', '/ˈɒpəreɪtɪŋ ˈmɒdəl/', 'noun', '{"zh-TW":["運營模式"],"en":["the way an organization structures its people, processes, and technology to deliver value"]}', NULL, 'define the operating model / redesign the operating model', '[{"en":"The company redesigned its operating model to improve customer service.","zh-TW":"公司重新設計了其運營模式以改善客戶服務。"},{"en":"A lean operating model reduces costs without compromising quality.","zh-TW":"精益運營模式在不犧牲品質的情況下降低了成本。"}]', NULL, NULL, 5, 4623, NULL),
(4624, 'operating profit', '/ˈɒpəreɪtɪŋ ˈprɒfɪt/', 'noun', '{"zh-TW":["營業利潤"],"en":["profit from core business operations before interest and taxes"]}', NULL, 'calculate operating profit / operating profit margin / improve operating profit', '[{"en":"Operating profit rose 12% despite flat revenue growth.","zh-TW":"儘管收入增長持平，營業利潤增長了12%。"},{"en":"The operating profit margin widened as costs were cut.","zh-TW":"隨著成本削減，營業利潤率擴大了。"}]', '{"abbreviation":"EBIT"}', NULL, 5, 4624, NULL),
(4625, 'operation', 'ˌɒpəˈreɪʃən', 'noun', '{"zh-TW":["運作；業務","操作"],"en":["a business activity","the way something works"]}', NULL, 'daily operations/overseas operations', '[{"en":"Managing daily operations efficiently.","zh-TW":"高效管理日常運作。"}]', '{"verb":"operate","adjective":"operational","adverb":"operationally"}', NULL, 3, 4625, NULL),
(4626, 'operational', 'ˌɒpəˈreɪʃənəl', 'adjective', '{"zh-TW":["運營的；操作的","可運行的"],"en":["relating to operations","ready to function"]}', NULL, 'operational efficiency/operational costs', '[{"en":"We focus on reducing operational costs.","zh-TW":"我們專注於降低運營成本。"}]', '{"noun":"operation","adverb":"operationally"}', NULL, 4, 4626, NULL),
(4627, 'operational cost', '/ˌɒpəˈreɪʃənəl kɒst/', 'noun', '{"zh-TW":["運營成本"],"en":["the expenses associated with running a business"]}', NULL, 'reduce operational costs / operational cost structure', '[{"en":"Technology investments have reduced operational costs significantly.","zh-TW":"技術投資大幅降低了運營成本。"},{"en":"Streamlining processes helps control operational costs.","zh-TW":"簡化流程有助於控制運營成本。"}]', NULL, NULL, 5, 4627, NULL),
(4628, 'operational efficiency', '/ˌɒpəˈreɪʃənl ɪˈfɪʃənsi/', 'noun', '{"zh-TW":["運營效率"],"en":["using the minimum required inputs to deliver the maximum possible output"]}', NULL, 'improve operational efficiency / operational efficiency gains', '[{"en":"Automation improved operational efficiency by reducing manual tasks.","zh-TW":"自動化通過減少人工任務提高了運營效率。"},{"en":"Operational efficiency improvements directly benefit the bottom line.","zh-TW":"運營效率提升直接有利於最終利潤。"}]', NULL, NULL, 5, 4628, NULL),
(4629, 'operational risk', '/ˌɒpəˈreɪʃənl rɪsk/', 'noun', '{"zh-TW":["運營風險"],"en":["the risk of loss from failed internal processes, people, or systems"]}', NULL, 'manage operational risk / operational risk framework', '[{"en":"The company identified human error as its highest operational risk.","zh-TW":"公司確定了人為錯誤作為其最高的運營風險。"},{"en":"An operational risk management system helps prevent financial losses.","zh-TW":"運營風險管理系統有助於防止財務損失。"}]', NULL, NULL, 5, 4629, NULL),
(4630, 'operations management', '/ˌɒpəˈreɪʃənz ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["營運管理"],"en":["overseeing the production of goods and services efficiently"]}', NULL, 'operations management strategy / operations management team', '[{"en":"Operations management ensures products are delivered on time and within cost.","zh-TW":"營運管理確保產品按時按成本交付。"},{"en":"He studied operations management to improve supply chain efficiency.","zh-TW":"他學習了營運管理以提高供應鏈效率。"}]', '{"noun":"operations manager"}', NULL, 5, 4630, NULL),
(4631, 'operations manual', '/ˌɒpəˈreɪʃənz ˈmænjuəl/', 'noun', '{"zh-TW":["操作手冊；業務操作手冊"],"en":["a document describing how processes and procedures are performed"]}', NULL, 'prepare an operations manual / refer to the operations manual', '[{"en":"The new operations manual was distributed to all site managers.","zh-TW":"新的操作手冊已分發給所有現場管理人員。"},{"en":"An operations manual ensures consistency across locations.","zh-TW":"操作手冊確保了各地點的一致性。"}]', NULL, NULL, 5, 4631, NULL),
(4632, 'ophthalmology', '/ˌɒfθælˈmɒlədʒi/', 'noun', '{"zh-TW":["眼科；眼科學"],"en":["the branch of medicine dealing with eye disorders"]}', NULL, 'ophthalmology appointment / ophthalmology clinic', '[{"en":"An ophthalmology examination detected early signs of glaucoma.","zh-TW":"眼科檢查發現了青光眼的早期跡象。"},{"en":"Children should have an ophthalmology checkup before school age.","zh-TW":"兒童應在學齡前接受眼科檢查。"}]', '{"noun":"ophthalmologist","adjective":"ophthalmological"}', NULL, 5, 4632, NULL),
(4633, 'opinion', '/əˈpɪnjən/', 'noun', '{"zh-TW":["意見；看法"],"en":["a personal belief or judgment"]}', '{"root":{"text":"opin","meaning":"think (認為)"},"suffix":{"text":"-ion","meaning":"名詞後綴"}}', 'in my opinion / public opinion', '[{"en":"In my opinion, we should postpone the launch.","zh-TW":"我認為應推遲發布。"},{"en":"Public opinion is shifting.","zh-TW":"民意正在轉變。"}]', '{"adjective":"opinionated"}', NULL, 3, 4633, NULL),
(4634, 'opponent', '/əˈpoʊnənt/', 'noun', '{"zh-TW":["對手；反對者"],"en":["one who competes against"]}', '{"prefix":{"text":"op-","meaning":"against"},"root":{"text":"pon","meaning":"put (放)"},"suffix":{"text":"-ent","meaning":"人"}}', 'political opponent / defeat an opponent', '[{"en":"Our main opponent is a multinational firm.","zh-TW":"我們的主要對手是跨國公司。"},{"en":"She defeated her opponent.","zh-TW":"她擊敗了對手。"}]', '{"verb":"oppose","noun":"opposition","adjective":"opposing"}', NULL, 3, 4634, NULL),
(4635, 'opportunity', '/ˌɒpərˈtjuːnɪti/', 'noun', '{"zh-TW":["機會"],"en":["a chance to do something"]}', '{"root":{"text":"portun","meaning":"port (港口)"},"suffix":{"text":"-ity","meaning":"狀態"}}', 'seize an opportunity / job opportunity', '[{"en":"This internship is a great opportunity.","zh-TW":"這實習是個好機會。"},{"en":"Seize every opportunity to expand.","zh-TW":"抓住每個擴展機會。"}]', '{"adjective":"opportune","noun":"opportunist"}', NULL, 4, 4635, 167),
(4636, 'opportunity cost', '/ˌɒpəˈtjuːnɪti kɒst/', 'noun', '{"zh-TW":["機會成本"],"en":["the value of the next best alternative that is foregone when a choice is made"]}', NULL, 'consider opportunity cost / high opportunity cost', '[{"en":"Investing in the building has a high opportunity cost of lost working capital.","zh-TW":"投資於建築物的機會成本是喪失的營運資金。"},{"en":"Understanding opportunity cost is essential for good resource allocation.","zh-TW":"了解機會成本對良好的資源分配至關重要。"}]', NULL, NULL, 5, 4636, NULL),
(4637, 'opportunity set', '/ˌɒpəˈtjuːnɪti set/', 'noun', '{"zh-TW":["機會集；投資機會集合"],"en":["the range of investment options available to an investor"]}', NULL, 'expand opportunity set / investment opportunity set / global opportunity set', '[{"en":"A global opportunity set offers investors access to assets across all markets and asset classes.","zh-TW":"全球機會集為投資者提供跨所有市場和資產類別的資產獲取機會。"},{"en":"Diversifying across a wider opportunity set can improve risk-adjusted returns.","zh-TW":"在更廣泛的機會集中進行多元化投資可以改善風險調整後的回報。"}]', NULL, NULL, 5, 4637, NULL),
(4638, 'oppose', '/əˈpoʊz/', 'verb', '{"zh-TW":["反對；對抗"],"en":["to disagree with or resist"]}', '{"prefix":{"text":"op-","meaning":"against"},"root":{"text":"pos","meaning":"put (放)"}}', 'oppose a plan / as opposed to', '[{"en":"Several senators opposed the legislation.","zh-TW":"幾位參議員反對立法。"},{"en":"As opposed to last year, profits increased.","zh-TW":"與去年相反，利潤增加了。"}]', '{"noun":"opposition","adjective":"opposite, opposing"}', NULL, 2, 4638, NULL),
(4639, 'opt', '/ɒpt/', 'verb', '{"zh-TW":["選擇；決定"],"en":["to make a choice"]}', '{"root":{"text":"opt","meaning":"choose (選)"}}', 'opt for / opt out / opt in', '[{"en":"Many employees opted for early retirement.","zh-TW":"許多員工選擇提前退休。"},{"en":"You can opt out of the mailing list.","zh-TW":"你可以退出郵件列表。"}]', '{"noun":"option","adjective":"optional"}', NULL, 1, 4639, NULL),
(4640, 'opt in', '/ɒpt ɪn/', 'verb', '{"zh-TW":["選擇加入；選擇接受"],"en":["to choose to participate in something"]}', NULL, 'opt in to a newsletter / opt in to a program', '[{"en":"Users can opt in to receive promotional emails.","zh-TW":"用戶可以選擇接收促銷電子郵件。"},{"en":"Employees must actively opt in to the wellness program.","zh-TW":"員工必須主動選擇加入健康促進計劃。"}]', '{"noun":"opt-in","adjective":"opt-in"}', NULL, 2, 4640, NULL),
(4641, 'opt out', '/ɒpt aʊt/', 'verb', '{"zh-TW":["選擇退出；拒絕參與"],"en":["to choose not to participate in something"]}', NULL, 'opt out of a mailing list / opt out option', '[{"en":"You can opt out of marketing emails at any time.","zh-TW":"您可以隨時選擇退出行銷電子郵件。"},{"en":"The employee opted out of the voluntary overtime program.","zh-TW":"員工選擇退出自願加班計劃。"}]', '{"noun":"opt-out","adjective":"opt-out"}', NULL, 3, 4641, NULL),
(4642, 'optimistic', '/ˌɒptɪˈmɪstɪk/', 'adjective', '{"zh-TW":["樂觀的"],"en":["hopeful and confident about the future"]}', '{"root":{"text":"optim","meaning":"best (最好)"},"suffix":{"text":"-istic","meaning":"characterized by (以…為特徵)"},"logic":"以看到最好的面為特徵的，即「樂觀的」。"}', 'optimistic outlook / cautiously optimistic', '[{"en":"She is optimistic about the future.","zh-TW":"她對未來持樂觀態度。"},{"en":"The report paints an optimistic picture.","zh-TW":"報告描繪了樂觀的景象。"}]', '{"noun":"optimism","noun2":"optimist","adverb":"optimistically"}', NULL, 4, 4642, NULL),
(4643, 'optimization', '/ˌɒptɪmaɪˈzeɪʃən/', 'noun', '{"zh-TW":["優化"],"en":["the process of making something as effective or efficient as possible"]}', NULL, 'process optimization / route optimization', '[{"en":"Supply chain optimization reduced delivery times by 20%.","zh-TW":"供應鏈優化將交貨時間縮短了20%。"},{"en":"The company hired a data analyst to assist with pricing optimization.","zh-TW":"公司聘請了數據分析師協助定價優化。"}]', '{"verb":"optimize","adjective":"optimized"}', NULL, 4, 4643, 601),
(4644, 'optimize', '/ˈɒptɪmaɪz/', 'verb', '{"zh-TW":["優化；使最優化"],"en":["to make as effective or efficient as possible"]}', NULL, 'optimize performance / optimize costs / optimize the supply chain', '[{"en":"The engineer optimized the algorithm to run twice as fast.","zh-TW":"工程師優化了算法，使其速度提高了一倍。"},{"en":"Optimizing inventory levels reduced carrying costs significantly.","zh-TW":"優化庫存水準顯著降低了持有成本。"}]', '{"noun":"optimization","adjective":"optimized"}', NULL, 3, 4644, 702),
(4645, 'option', '/ˈɒpʃən/', 'noun', '{"zh-TW":["選項","期權"],"en":["a choice","right to buy/sell at set price"]}', '{"root":{"text":"opt","meaning":"choose (選)"},"suffix":{"text":"-ion","meaning":"名詞後綴"}}', 'available options / stock option', '[{"en":"We have several options to consider.","zh-TW":"我們有幾個選項。"},{"en":"The company offers stock options.","zh-TW":"公司提供股票期權。"}]', '{"adjective":"optional","verb":"opt"}', NULL, 2, 4645, 402),
(4646, 'option contract', '/ˈɒpʃən ˈkɒntrækt/', 'noun', '{"zh-TW":["選擇權合約；期權合約"],"en":["a financial instrument giving the right to buy or sell an asset at a set price"]}', NULL, 'buy an option contract / exercise an option contract', '[{"en":"The option contract gave the company the right to acquire the land.","zh-TW":"選擇權合約賦予公司收購土地的權利。"},{"en":"Investors use option contracts to hedge downside risk.","zh-TW":"投資者使用期權合約對沖下行風險。"}]', NULL, NULL, 5, 4646, NULL),
(4647, 'options', '/ˈɒpʃənz/', 'noun', '{"zh-TW":["選擇權；期權"],"en":["contracts giving the right to buy or sell an asset at a set price"]}', NULL, 'call option / put option / exercise options / options contract', '[{"en":"He bought call options on the rising stock.","zh-TW":"他購買了上漲股票的買入選擇權。"},{"en":"Employee stock options are a common form of compensation.","zh-TW":"員工股票選擇權是一種常見的薪酬形式。"}]', '{"singular":"option"}', NULL, 3, 4647, NULL),
(4648, 'oral', '/ˈɔːrəl/', 'adjective', '{"zh-TW":["口頭的"],"en":["spoken, not written"]}', '{"root":{"text":"or","meaning":"mouth (嘴)"},"suffix":{"text":"-al","meaning":"...的"}}', 'oral presentation / oral agreement', '[{"en":"The contract was only an oral agreement.","zh-TW":"合約只是口頭協議。"},{"en":"Each student must give an oral presentation.","zh-TW":"每人須做口頭報告。"}]', '{"adverb":"orally"}', NULL, 1, 4648, NULL),
(4649, 'oral agreement', '/ˈɔːrəl əˈɡriːmənt/', 'noun', '{"zh-TW":["口頭協議"],"en":["a verbal contract not documented in writing"]}', NULL, 'rely on an oral agreement / oral agreement enforceability', '[{"en":"An oral agreement may be enforceable but is difficult to prove.","zh-TW":"口頭協議可能具有可執行性，但難以證明。"},{"en":"They should document all terms since the oral agreement is insufficient.","zh-TW":"由於口頭協議不夠充分，他們應記錄所有條款。"}]', NULL, NULL, 5, 4649, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(4650, 'oral presentation', '/''ɔːrəl ˌprezənˈteɪʃən/', 'noun', '{"zh-TW":["口頭報告；口頭簡報"],"en":["a prepared speech or talk given to an audience, often as part of an academic or professional context"]}', NULL, 'deliver an oral presentation / prepare an oral presentation / oral presentation skill', '[{"en":"Students must deliver an oral presentation of their research findings at the end of the term.","zh-TW":"學生必須在學期末就其研究結果進行口頭報告。"},{"en":"A well-structured oral presentation keeps the audience engaged and informed.","zh-TW":"結構良好的口頭報告能讓聽眾保持參與並獲得資訊。"}]', '{"adjective":"oral","verb":"present"}', NULL, 5, 4650, NULL),
(4651, 'orchestra', '/ˈɔːrkɪstrə/', 'noun', '{"zh-TW":["管弦樂團"],"en":["a large group of musicians playing various instruments"]}', '{"root":{"text":"orchestra","meaning":"dancing place (舞蹈場)"},"logic":"源自希臘語，原指劇場中合唱團的表演場地。"}', 'symphony orchestra / orchestra pit', '[{"en":"The orchestra performed Beethoven''s Fifth Symphony.","zh-TW":"管弦樂團演奏了貝多芬第五號交響曲。"},{"en":"She plays violin in the city orchestra.","zh-TW":"她在市立管弦樂團拉小提琴。"}]', '{"adjective":"orchestral","verb":"orchestrate"}', NULL, 3, 4651, NULL),
(4652, 'orchestration', '/ˌɔːrkɪˈstreɪʃən/', 'noun', '{"zh-TW":["服務編排；協調"],"en":["the automated management and coordination of complex systems or services"]}', NULL, 'container orchestration / workflow orchestration / cloud orchestration', '[{"en":"Kubernetes is the leading platform for container orchestration.","zh-TW":"Kubernetes是容器編排的領先平台。"},{"en":"Orchestration tools coordinate hundreds of microservices in production.","zh-TW":"編排工具在生產環境中協調數百個微服務。"}]', '{"verb":"orchestrate","adjective":"orchestrated"}', NULL, 5, 4652, NULL),
(4653, 'order', '/ˈɔːrdər/', 'noun', '{"zh-TW":["【主要意義-動詞/名詞】命令；訂單；訂購","【次要意義-名詞】次序；順序；狀態","【次要意義-名詞】（機器）運作狀態"],"en":["[primary] a command; a request to supply goods","[secondary - noun] the arrangement or sequence of things","[secondary - noun] the condition of working properly"]}', NULL, 'in order / out of order / in good working order / order of business / tall order', '[{"en":"The photocopier is out of order until further notice.","zh-TW":"影印機暫時故障，待通知修復。"},{"en":"Please address agenda items in the order listed.","zh-TW":"請按照表格上列出的順序處理議程事項。"},{"en":"Completing this project in two days is a tall order.","zh-TW":"在兩天內完成這個專案要求很高，但我們會盡力。"}]', '{"adjective":"orderly","noun":"orderliness"}', 'order 的次要意義包括「次序」和「運作狀態」，常見片語：out of order（故障/不合規定）、in order（按順序/正常）、tall order（難以完成的要求）均為 TOEIC 高頻表達。', 2, 4653, 43),
(4654, 'order backlog', '/ˈɔːrdər ˈbæklɒɡ/', 'noun', '{"zh-TW":["積壓訂單；未完成訂單"],"en":["the volume of customer orders that have been received but not yet fulfilled"]}', NULL, 'reduce the order backlog / order backlog growth', '[{"en":"A growing order backlog indicated strong demand for the company''s products.","zh-TW":"不斷增長的積壓訂單表明了市場對公司產品的強勁需求。"},{"en":"The company hired additional staff to clear the order backlog quickly.","zh-TW":"公司聘請了額外的人員以快速清除積壓訂單。"}]', NULL, NULL, 5, 4654, NULL),
(4655, 'order confirmation', '/ˈɔːrdər ˌkɒnfɜːˈmeɪʃən/', 'noun', '{"zh-TW":["訂單確認"],"en":["a document from a seller confirming receipt and details of a customer order"]}', NULL, 'issue an order confirmation / order confirmation number', '[{"en":"Customers receive an order confirmation by email within minutes.","zh-TW":"客戶在幾分鐘內通過電子郵件收到訂單確認。"},{"en":"Check the order confirmation for accuracy before proceeding.","zh-TW":"在繼續之前檢查訂單確認的準確性。"}]', NULL, NULL, 5, 4655, NULL),
(4656, 'order fulfillment', '/ˈɔːrdər fʊlˈfɪlmənt/', 'noun', '{"zh-TW":["訂單履行"],"en":["the process from receiving an order to delivering it to the customer"]}', NULL, 'improve order fulfillment / order fulfillment rate', '[{"en":"The company improved order fulfillment speed by automating the warehouse.","zh-TW":"公司通過自動化倉庫提高了訂單履行速度。"},{"en":"Order fulfillment accuracy is tracked as a key performance indicator.","zh-TW":"訂單履行準確性作為關鍵績效指標進行追蹤。"}]', NULL, NULL, 5, 4656, NULL),
(4657, 'order management', '/ˈɔːrdər ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["訂單管理"],"en":["the process of receiving, processing, and fulfilling customer orders"]}', NULL, 'improve order management / order management system', '[{"en":"The order management system reduced processing errors by 40%.","zh-TW":"訂單管理系統將處理錯誤減少了40%。"},{"en":"Effective order management ensures on-time delivery and accurate invoicing.","zh-TW":"有效的訂單管理確保了準時交貨和準確的發票開立。"}]', NULL, NULL, 5, 4657, NULL),
(4658, 'ordinance', '/ˈɔːrdɪnəns/', 'noun', '{"zh-TW":["條例；法令"],"en":["a law made by a city or town"]}', NULL, 'city ordinance / local ordinance', '[{"en":"The city passed a new ordinance.","zh-TW":"市政府通過了一項新條例。"},{"en":"It violates a local ordinance.","zh-TW":"這違反了地方條例。"}]', NULL, NULL, 3, 4658, NULL),
(4659, 'ordinarily', '/ˌɔːrdɪˈnerɪli/', 'adverb', '{"zh-TW":["通常；通常情況下"],"en":["in normal circumstances; usually"]}', NULL, 'ordinarily expected / ordinarily required / ordinarily applied', '[{"en":"The court ruled that the standard of care is what a reasonably competent person would ordinarily do.","zh-TW":"法院裁定，注意標準是一個合理稱職的人通常會做的事情。"},{"en":"Ordinarily, shareholders vote on major strategic decisions at the annual general meeting.","zh-TW":"通常情況下，股東在年度股東大會上對重大戰略決策進行投票。"}]', '{"adjective":"ordinary"}', NULL, 4, 4659, NULL),
(4660, 'ordinary', '/ˈɔːrdɪneri/', 'adjective', '{"zh-TW":["普通的；平常的"],"en":["normal; not special"]}', '{"root":{"text":"ordin","meaning":"order (秩序)"},"suffix":{"text":"-ary","meaning":"...的"}}', 'ordinary people / out of the ordinary', '[{"en":"It was an ordinary day at the office.","zh-TW":"辦公室平常的一天。"},{"en":"Nothing out of the ordinary happened.","zh-TW":"沒什麼不尋常的事。"}]', '{"adverb":"ordinarily"}', NULL, 3, 4660, NULL),
(4661, 'organic', '/ɔːrˈɡænɪk/', 'adjective', '{"zh-TW":["有機的"],"en":["produced without artificial chemicals"]}', NULL, 'organic produce / organic ingredients', '[{"en":"The restaurant uses organic vegetables from local farms.","zh-TW":"餐廳使用來自當地農場的有機蔬菜。"},{"en":"Organic food has become increasingly popular.","zh-TW":"有機食品越來越受歡迎。"}]', '{"adverb":"organically","noun":"organism"}', NULL, 3, 4661, NULL),
(4662, 'organic farming', '/''ɔːrɡænɪk ˌfɑːrmɪŋ/', 'noun', '{"zh-TW":["有機農業"],"en":["a method of farming that avoids the use of synthetic chemicals and relies on natural processes"]}', NULL, 'practice organic farming / transition to organic farming / organic farming certification', '[{"en":"Organic farming supports biodiversity and reduces chemical runoff into waterways.","zh-TW":"有機農業支持生物多樣性，減少化學物質流入水道。"},{"en":"Consumer demand for pesticide-free produce has driven the growth of organic farming.","zh-TW":"消費者對無農藥農產品的需求推動了有機農業的增長。"}]', '{"adjective":"organic"}', NULL, 5, 4662, NULL),
(4663, 'organic growth', '/ɔːˈɡænɪk ɡrəʊθ/', 'noun', '{"zh-TW":["有機成長；內生增長"],"en":["growth achieved through internal processes rather than acquisitions"]}', NULL, 'achieve organic growth / organic growth strategy / sustained organic growth', '[{"en":"The firm focused on organic growth through product innovation.","zh-TW":"公司通過產品創新專注於有機成長。"},{"en":"Organic growth is generally more sustainable than growth from acquisitions.","zh-TW":"有機成長通常比收購帶來的增長更可持續。"}]', NULL, NULL, 5, 4663, NULL),
(4664, 'organic reach', '/ɔːˈɡænɪk riːtʃ/', 'noun', '{"zh-TW":["自然觸及"],"en":["the number of people who see content without paid promotion"]}', NULL, 'increase organic reach / decline in organic reach', '[{"en":"Organic reach on social media has decreased as platforms push paid ads.","zh-TW":"隨著平台推動付費廣告，社群媒體的自然觸及率下降了。"},{"en":"Quality content improves organic reach on search engines.","zh-TW":"高品質的內容提高了在搜尋引擎上的自然觸及。"}]', NULL, NULL, 5, 4664, NULL),
(4665, 'organizational behavior', '/ˌɔːrɡənɪˈzeɪʃənl bɪˈheɪvjər/', 'noun', '{"zh-TW":["組織行為"],"en":["the study of how people behave within organizational settings"]}', NULL, 'study organizational behavior / organizational behavior theory', '[{"en":"Understanding organizational behavior helps managers improve team effectiveness.","zh-TW":"理解組織行為幫助管理者提高團隊效率。"},{"en":"Organizational behavior research informs leadership development programs.","zh-TW":"組織行為研究為領導力發展計劃提供依據。"}]', NULL, NULL, 5, 4665, NULL),
(4666, 'organizational chart', '/ˌɔːrɡənəˈzeɪʃənl tʃɑːrt/', 'noun', '{"zh-TW":["組織架構圖"],"en":["a diagram showing the structure of an organization"]}', NULL, 'draw up an organizational chart / update the organizational chart', '[{"en":"The organizational chart shows who reports to whom.","zh-TW":"組織架構圖顯示了誰向誰匯報。"},{"en":"The new organizational chart reflects the restructuring.","zh-TW":"新組織架構圖反映了重組情況。"}]', '{"adjective":"organizational"}', NULL, 5, 4666, NULL),
(4667, 'organizational culture', '/''ɔːrɡənɪˌzeɪʃənəl ˌkʌltʃər/', 'noun', '{"zh-TW":["組織文化"],"en":["the shared values, beliefs, and practices that shape how members of an organization interact and work"]}', NULL, 'build organizational culture / change organizational culture / positive organizational culture', '[{"en":"A strong organizational culture can attract talented employees and reduce turnover.","zh-TW":"強大的組織文化可以吸引有才能的員工並降低離職率。"},{"en":"Changes to organizational culture require leadership commitment over a sustained period.","zh-TW":"組織文化的改變需要領導層在一段持續時間內的承諾。"}]', '{"adjective":"organizational"}', NULL, 5, 4667, NULL),
(4668, 'organizational effectiveness', '/ˌɔːrɡənɪˈzeɪʃənl ɪˈfektɪvnɪs/', 'noun', '{"zh-TW":["組織效能"],"en":["the degree to which an organization achieves its goals efficiently"]}', NULL, 'improve organizational effectiveness / measure organizational effectiveness', '[{"en":"Leadership training improved organizational effectiveness across departments.","zh-TW":"領導力培訓改善了各部門的組織效能。"},{"en":"Organizational effectiveness is assessed through KPIs and employee surveys.","zh-TW":"組織效能通過關鍵績效指標和員工調查進行評估。"}]', NULL, NULL, 5, 4668, NULL),
(4669, 'organizational restructuring', '/ˌɔːrɡənɪˈzeɪʃənl riːˈstrʌktʃərɪŋ/', 'noun', '{"zh-TW":["組織重組"],"en":["reorganizing a company structure to improve efficiency or align strategy"]}', NULL, 'undergo organizational restructuring / organizational restructuring plan', '[{"en":"Organizational restructuring merged three divisions into one.","zh-TW":"組織重組將三個部門合併為一個。"},{"en":"The organizational restructuring improved reporting lines and accountability.","zh-TW":"組織重組改善了匯報線和問責制。"}]', NULL, NULL, 5, 4669, NULL),
(4670, 'organize', '/ˈɔːrɡənaɪz/', 'verb', '{"zh-TW":["組織；安排"],"en":["to plan and arrange"]}', '{"root":{"text":"organ","meaning":"instrument (工具)"},"suffix":{"text":"-ize","meaning":"使...化"}}', 'organize an event / well-organized', '[{"en":"She organized the annual conference.","zh-TW":"她組織了年度會議。"},{"en":"You need to organize your workspace.","zh-TW":"你需要整理工作空間。"}]', '{"noun":"organization, organizer","adjective":"organizational"}', NULL, 3, 4670, NULL),
(4671, 'organized', 'ˈɔːrɡənaɪzd', 'adjective', '{"zh-TW":["有組織的；有條理的","整齊的"],"en":["arranged in an orderly way","systematic"]}', NULL, 'organized approach/organized workspace', '[{"en":"Keep your workspace organized.","zh-TW":"保持工作空間整齊有序。"}]', '{"verb":"organize","noun":"organization","adverb":"in an organized manner"}', NULL, 3, 4671, NULL),
(4672, 'orient', '/ˈɔːriɛnt/', 'verb', '{"zh-TW":["使適應；定向"],"en":["to help become familiar with"]}', '{"root":{"text":"ori","meaning":"rise (升起)"}}', 'orient oneself / market-oriented', '[{"en":"The program helps orient new employees.","zh-TW":"計劃幫助新員工適應。"},{"en":"The company is customer-oriented.","zh-TW":"公司以客戶為導向。"}]', '{"noun":"orientation","adjective":"oriented"}', NULL, 2, 4672, NULL),
(4673, 'orientation', '/ˌɔːriɛnˈteɪʃən/', 'noun', '{"zh-TW":["迎新；方向"],"en":["an introduction to a new situation"]}', NULL, 'orientation day / student orientation', '[{"en":"New student orientation is next Monday.","zh-TW":"新生迎新活動下週一舉行。"},{"en":"The orientation covers campus rules.","zh-TW":"迎新活動涵蓋了校規。"}]', NULL, NULL, 4, 4673, 404),
(4674, 'orientation week', '/''ɔːriənˈteɪʃən wiːk/', 'noun', '{"zh-TW":["迎新週；入學輔導週"],"en":["a week at the start of a new academic year when students are introduced to the institution and its programs"]}', NULL, 'attend orientation week / orientation week activities / university orientation week', '[{"en":"Orientation week helps new students get familiar with the campus and their program.","zh-TW":"迎新週幫助新生熟悉校園和他們的課程。"},{"en":"During orientation week, students meet their professors and fellow classmates.","zh-TW":"在迎新週期間，學生們與教授和同學見面。"}]', NULL, NULL, 5, 4674, NULL),
