(4677, 'origination', '/əˌrɪdʒɪˈneɪʃən/', 'noun', '{"zh-TW":["發起；貸款發放"],"en":["the process of creating a loan or financial instrument"]}', NULL, 'loan origination / origination fee / origination process', '[{"en":"Origination fees are charged by lenders at the beginning of a loan.","zh-TW":"貸款發放費由貸款方在貸款開始時收取。"},{"en":"The bank streamlined its mortgage origination process using digital tools.","zh-TW":"銀行使用數字工具簡化了其抵押貸款發放流程。"}]', '{"verb":"originate","adjective":"originated"}', NULL, 4, 4677, NULL),
(4678, 'orthopedics', '/ˌɔːrθəˈpiːdɪks/', 'noun', '{"zh-TW":["骨科；矯形外科"],"en":["the branch of medicine dealing with bones and muscles"]}', NULL, 'orthopedics consultation / orthopedics surgery', '[{"en":"He visited the orthopedics clinic for his knee injury.","zh-TW":"他前往骨科診所治療膝蓋傷。"},{"en":"Orthopedics surgeons treat fractures and joint problems.","zh-TW":"骨科外科醫生治療骨折和關節問題。"}]', '{"noun":"orthopedic surgeon","adjective":"orthopedic"}', NULL, 4, 4678, NULL),
(4679, 'ostensible', '/ɒˈstensɪbəl/', 'adjective', '{"zh-TW":["表面上的；外表的"],"en":["appearing or stated as such, but not necessarily so"]}', NULL, 'ostensible reason / ostensible purpose / ostensible goal', '[{"en":"The ostensible goal of the merger was to reduce costs.","zh-TW":"合併的表面目標是降低成本。"},{"en":"His ostensible enthusiasm hid a deeper reluctance to comply.","zh-TW":"他表面上的熱情掩蓋了更深層的不情願。"}]', '{"adverb":"ostensibly"}', NULL, 4, 4679, NULL),
(4680, 'ostensibly', '/''ɒˈstensɪbli/', 'adverb', '{"zh-TW":["表面上看；看似"],"en":["as it appears or is stated, but not necessarily so; apparently"]}', NULL, 'ostensibly simple / ostensibly for / ostensibly independent', '[{"en":"The merger was ostensibly done to improve efficiency, but critics saw other motives.","zh-TW":"合併表面上是為了提高效率，但批評者看到了其他動機。"},{"en":"The company''s ostensibly charitable donation was seen as a marketing strategy.","zh-TW":"公司表面上的慈善捐款被視為一種行銷策略。"}]', '{"adjective":"ostensible"}', NULL, 4, 4680, NULL),
(4681, 'ostracize', '/ˈɒstrəsaɪz/', 'verb', '{"zh-TW":["排斥；放逐"],"en":["to exclude from a group or society"]}', NULL, 'ostracize a member / socially ostracized / ostracize dissidents', '[{"en":"Members who violate group norms risk being ostracized.","zh-TW":"違反群體規範的成員可能面臨被排斥的風險。"},{"en":"The scholar was ostracized for challenging the prevailing consensus.","zh-TW":"這位學者因挑戰主流共識而被排斥。"}]', '{"noun":"ostracism","adjective":"ostracized"}', NULL, 3, 4681, NULL),
(4682, 'othering', '/ˈʌðərɪŋ/', 'noun', '{"zh-TW":["他者化；邊界化"],"en":["the process of viewing or treating a group as fundamentally different and inferior"]}', NULL, 'practice of othering / othering of minorities / resist othering', '[{"en":"The rhetoric of othering has been used to justify discrimination and exclusion.","zh-TW":"他者化的言論被用於為歧視和排斥辯護。"},{"en":"Educators aim to counter othering by promoting empathy and inclusion.","zh-TW":"教育者旨在通過促進同理心和包容性來對抗他者化。"}]', '{"verb":"other"}', NULL, 3, 4682, NULL),
(4683, 'otherwise', '/ˈʌðərwaɪz/', 'adverb', '{"zh-TW":["否則","在其他方面"],"en":["if not; or else","in other ways"]}', NULL, 'unless otherwise stated', '[{"en":"Submit by Friday; otherwise, it will be late.","zh-TW":"週五前提交；否則就遲了。"},{"en":"Unless otherwise stated, it applies to all.","zh-TW":"除非另有說明，適用於全部。"}]', NULL, NULL, 3, 4683, NULL),
