(4695, 'outlier', '/''aʊtˌlaɪər/', 'noun', '{"zh-TW":["離群值；例外情況；異常現象"],"en":["a person or thing that is different from or in a different situation from the expected norm"]}', NULL, 'statistical outlier / identify an outlier / outlier in the data', '[{"en":"The unusually high sales figure was an outlier that skewed the entire dataset.","zh-TW":"異常高的銷售數字是一個使整個數據集產生偏差的離群值。"},{"en":"His rapid career advancement made him an outlier in a very competitive industry.","zh-TW":"他快速的職業晉升使他成為一個極具競爭力行業中的例外情況。"}]', '{"adjective":"outlier"}', NULL, 3, 4695, NULL),
